package com.trampolim.api.career;
import java.util.*;import java.time.*;import static com.trampolim.api.radar.RadarModel.*;import com.trampolim.api.radar.*;import org.springframework.web.bind.annotation.*;import org.springframework.beans.factory.annotation.Qualifier;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;
@RestController public class CareerRegionalController {
 private final JdbcTemplate jdbc;private final SkillCatalog users;private final RadarBridge bridge;
 public CareerRegionalController(@Qualifier("jdbcTemplate")JdbcTemplate jdbc,SkillCatalog users,RadarBridge bridge){this.jdbc=jdbc;this.users=users;this.bridge=bridge;}
 public record Consent(String regionCode,boolean consent){}public record Rating(int rating){}public record Preview(String code,boolean consent,boolean publicMetricsConsent){}
 public record Demand(long id,int revision){}public record Query(int version,String region,String from,String to,List<Demand> demands,List<Long> publicPrograms){}
 @GetMapping("/api/career/observatory/consent")public List<Map<String,Object>> consent(@AuthenticationPrincipal String email){return jdbc.queryForList("SELECT region_code,consent_at FROM career_observatory_consents WHERE user_id=?",users.user(email));}
 @PutMapping("/api/career/observatory/consent")@ResponseStatus(HttpStatus.NO_CONTENT)public void consent(@AuthenticationPrincipal String email,@RequestBody Consent input){long uid=users.user(email);if(input==null||!input.consent())bad("Autorize a participação em indicadores regionais agregados.");jdbc.update("INSERT INTO career_observatory_consents(user_id,region_code) VALUES (?,?) ON CONFLICT(user_id) DO UPDATE SET region_code=EXCLUDED.region_code,consent_at=CURRENT_TIMESTAMP",uid,CareerRules.region(input.regionCode(),false));}
 @DeleteMapping("/api/career/observatory/consent")@ResponseStatus(HttpStatus.NO_CONTENT)public void revoke(@AuthenticationPrincipal String email){jdbc.update("DELETE FROM career_observatory_consents WHERE user_id=?",users.user(email));}
 @DeleteMapping("/api/career/satisfaction")@ResponseStatus(HttpStatus.NO_CONTENT)public void removeRating(@AuthenticationPrincipal String email){jdbc.update("DELETE FROM career_satisfaction WHERE user_id=?",users.user(email));}
 @PutMapping("/api/career/satisfaction")@ResponseStatus(HttpStatus.NO_CONTENT)public void rating(@AuthenticationPrincipal String email,@RequestBody Rating input){if(input==null||input.rating()<1||input.rating()>5)bad("Informe uma avaliação de 1 a 5.");jdbc.update("INSERT INTO career_satisfaction(user_id,rating) VALUES (?,?) ON CONFLICT(user_id) DO UPDATE SET rating=EXCLUDED.rating,updated_at=CURRENT_TIMESTAMP",users.user(email),input.rating());}
 @GetMapping("/api/career/observatory")public Map<String,Object> observatory(@AuthenticationPrincipal String email,@RequestParam(defaultValue="")String region,@RequestParam String from,@RequestParam String to){users.user(email);CareerRules.dates(from,to);return bridge.convert(bridge.get("/public/career/observatory?region="+CareerRules.region(region,true)+"&from="+from+"&to="+to),Map.class);}
 @GetMapping("/api/career/young-opportunities")public Map<String,Object> young(@AuthenticationPrincipal String email,@RequestParam(defaultValue="")String regime,@RequestParam(defaultValue="")String region,@RequestParam(defaultValue="false")boolean first,@RequestParam(defaultValue="9223372036854775807")long before,@RequestParam(defaultValue="20")int limit){users.user(email);CareerRules.page(before,limit);if(!Set.of("","EMPLOYMENT","INTERNSHIP","APPRENTICESHIP").contains(regime))bad("Regime inválido.");return bridge.convert(bridge.get("/public/career/opportunities?region="+CareerRules.region(region,true)+"&regime="+regime+"&first="+first+"&before="+before+"&limit="+limit),Map.class);}
 @PostMapping("/api/career/outcomes/preview")public Map<String,Object> preview(@AuthenticationPrincipal String email,@RequestBody Preview input){users.user(email);if(input==null)bad("Informe o código.");return bridge.convert(bridge.post("/integrations/career/outcomes/preview",new CompanySelectionService.Confirmation(1,input.code(),email,false,false)),Map.class);}
 @PostMapping("/api/career/outcomes/confirm")public Map<String,Object> confirm(@AuthenticationPrincipal String email,@RequestBody Preview input){users.user(email);if(input==null||!input.consent())bad("Confirme o resultado informado após revisar os dados da empresa.");return bridge.convert(bridge.post("/integrations/career/outcomes/confirm",new CompanySelectionService.Confirmation(1,input.code(),email,true,input.publicMetricsConsent())),Map.class);}
 @PostMapping("/api/integrations/career/observatory/candidates")public Map<String,Object> aggregate(@RequestHeader(name="X-Trampolim-Bridge",required=false)String key,@RequestBody Query input){bridge.authorize(key);validate(input);String uf=CareerRules.region(input.region(),true);var args=new ArrayList<Object>();String cohort=" FROM career_observatory_consents c JOIN app_users u ON u.id=c.user_id AND u.email_verified=TRUE AND u.account_type='PERSON' WHERE (?='' OR c.region_code=?) AND c.consent_at>=? AND c.consent_at<?";args.add(uf);args.add(uf);args.add(LocalDate.parse(input.from()));args.add(LocalDate.parse(input.to()).plusDays(1));long participants=jdbc.queryForObject("SELECT count(*)"+cohort,Long.class,args.toArray());var result=new LinkedHashMap<String,Object>();result.put("participants",CareerRules.band(participants));if(participants<10){result.put("resolvedGaps",CareerRules.band(0));result.put("satisfaction",Map.of("available",false));result.put("gaps",List.of());return result;}
  var rating=jdbc.queryForMap("SELECT count(*) AS count,round(avg(s.rating),1) AS average FROM career_satisfaction s JOIN career_observatory_consents c ON c.user_id=s.user_id WHERE (?='' OR c.region_code=?) AND c.consent_at>=? AND c.consent_at<?",args.toArray());result.put("satisfaction",((Number)rating.get("count")).longValue()<10?Map.of("available",false):Map.of("available",true,"average",rating.get("average")));
  if(input.demands().isEmpty()){result.put("resolvedGaps",CareerRules.band(0));result.put("gaps",List.of());return result;}var scopeArgs=new ArrayList<Object>();for(var demand:input.demands()){scopeArgs.add(demand.id());scopeArgs.add(demand.revision());}scopeArgs.addAll(args);String scoped="WITH scope(id,revision) AS (VALUES "+String.join(",",Collections.nCopies(input.demands().size(),"(?::bigint,?::int)"))+"), cohort AS (SELECT s.* FROM future_talent_interests i JOIN future_preparation_snapshots s ON s.interest_id=i.id JOIN scope d ON d.id=i.demand_id AND d.revision=s.requirements_revision JOIN career_observatory_consents c ON c.user_id=i.user_id JOIN app_users u ON u.id=i.user_id AND u.email_verified=TRUE WHERE (?='' OR c.region_code=?) AND c.consent_at>=? AND c.consent_at<? AND s.checked_at>CURRENT_TIMESTAMP-INTERVAL '48 hours') ";var gaps=jdbc.queryForList(scoped+"SELECT gap AS skill_code,count(DISTINCT i.user_id) AS participants FROM cohort s JOIN future_talent_interests i ON i.id=s.interest_id CROSS JOIN LATERAL jsonb_array_elements_text(s.gaps) gap GROUP BY gap HAVING count(DISTINCT i.user_id)>=10 ORDER BY participants DESC,skill_code LIMIT 20",scopeArgs.toArray());for(var gap:gaps)gap.put("participants",CareerRules.band(((Number)gap.get("participants")).longValue()));result.put("gaps",gaps);long resolved=jdbc.queryForObject(scoped+"SELECT count(DISTINCT i.user_id) FROM cohort s JOIN future_talent_interests i ON i.id=s.interest_id WHERE EXISTS(SELECT 1 FROM jsonb_array_elements_text(s.baseline_gaps) g WHERE NOT s.gaps @> to_jsonb(g.value))",Long.class,scopeArgs.toArray());result.put("resolvedGaps",CareerRules.band(resolved));return result;}
 public static void validate(Query input){if(input==null||input.version()!=1||input.demands()==null||input.demands().size()>200||input.demands().stream().anyMatch(d->d==null||d.id()<1||d.revision()<0)||input.publicPrograms()==null||input.publicPrograms().size()>200||input.publicPrograms().stream().anyMatch(p->p==null||p<1))bad("Escopo regional inválido.");CareerRules.dates(input.from(),input.to());}
}
